/* ============================================================
   HERO — hero.module.css
   Extracted verbatim from boldteq-v1-0.webflow.css
   ============================================================ */

.section-high-judge {
  background-color: #0000;
  background-image: url('/images/webflow/hero-background-1.png'), linear-gradient(#019ae614, #019ae600);
  background-position: 50% 100%, 0 0;
  background-repeat: repeat, repeat;
  background-size: cover, auto;
  padding-top: 4rem;
  padding-bottom: 4rem;
  font-weight: 400;
  text-decoration: none;
}

.home-ban-judge {
  background-image: url('/images/webflow/hero-background-1.png'), linear-gradient(#019ae614, #019ae600);
  background-position: 50% 0, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: cover, auto;
}

.div-white-bag {
  position: relative;
  overflow-x: hidden;
}

.div-stuck-swept {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 2rem;
  padding-right: 2rem;
  font-weight: 400;
  text-decoration: none;
}

.div-wrote-smoke {
  text-align: center;
  color: #05bafe;
  max-width: 70rem;
  margin-left: auto;
  margin-right: auto;
  padding: 0;
  font-weight: 400;
  text-decoration: none;
}

.review-link {
  text-decoration: none;
}

.review-stars {
  background-color: #00b67a1a;
  border-radius: 10px;
  padding: 8px 10px;
}

.p-base-place {
  color: #092245;
  margin-top: 1.5rem;
  margin-bottom: 0;
  padding: 0;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 1.25;
  text-decoration: none;
}

.animate-span {
  color: #05bafe;
}

.p-base-place-copy {
  color: #092245;
  margin-top: 0;
  margin-bottom: 10px;
  padding: 0;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 1.25;
  text-decoration: none;
}

.h1-season-seeing {
  color: #2b2b2b;
  max-width: 52rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  text-decoration: none;
}

.div-job-attention {
  z-index: 1;
  justify-content: center;
  align-items: center;
  margin-top: 2rem;
  padding-left: 0;
  padding-right: 0;
  font-weight: 400;
  text-decoration: none;
  display: flex;
  position: relative;
}

.mob-left {
  /* applied at mobile only — see media query below */
}

.mob-margin-less {
  margin-top: 1rem;
}

.ban-grid {
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 0.75fr 0.85fr;
  grid-auto-columns: 1fr;
  max-width: 660px;
  margin-bottom: 50px;
  display: grid;
}

.margin-bottom-0 {
  margin-bottom: 0;
}

.hom-ban-grd {
  /* additional modifier — used with ban-grid.margin-bottom-0 */
}

.grid-box {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  background-color: #fff;
  border-radius: 10px;
  align-items: center;
  padding: 20px;
  transition: all 0.5s;
  display: flex;
  box-shadow: 0 0 5px #0000001a;
}

.home-grid-box {
  padding-top: 13px;
