/* ─── Outer footer section ───────────────────────────────────────────────────── */

.footer {
  background-color: #082753;
  padding: 72px 5% 16px;
  position: relative;
}

/* ─── Container ──────────────────────────────────────────────────────────────── */

.container-large-6 {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

/* ─── Outer column ───────────────────────────────────────────────────────────── */

.column-x-large {
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  flex-direction: column;
  display: flex;
}

/* ─── Two-column grid (newsletter | links) ───────────────────────────────────── */

.footer-grid {
  grid-column-gap: 3rem;
  grid-row-gap: 3rem;
  grid-template-rows: auto;
  grid-template-columns: 0.75fr 1.25fr;
  place-items: center stretch;
  display: grid;
}

/* ─── Left: newsletter side ──────────────────────────────────────────────────── */

.footer-main {
  grid-column-gap: 88px;
  grid-row-gap: 88px;
  flex-flow: row;
  max-width: none;
  display: flex;
}

/* ─── Newsletter card ────────────────────────────────────────────────────────── */

.footer-newsletter-card {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  opacity: 1;
  background-color: #ffffff4d;
  background-image: radial-gradient(circle, #092854, #092955ab);
  border: 0.5px solid #05bafe61;
  border-radius: 20px;
  flex-flow: column;
  padding: 30px;
  display: flex;
  box-shadow: 0 0 50px #0003, inset 0 0 100px #092955;
  width: 100%;
}

/* ─── Newsletter title block ─────────────────────────────────────────────────── */

.footer-newsletter-title {
  grid-column-gap: 0px;
  grid-row-gap: 0px;
  flex-flow: column;
  padding: 0;
  display: flex;
}

/* ─── "Join 500+ Subscribers" pill ──────────────────────────────────────────── */

.news-subhead-out {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  justify-content: flex-start;
  align-items: center;
  margin-bottom: 15px;
  display: flex;
}

.newsubott {
  grid-column-gap: 5px;
  grid-row-gap: 5px;
  background-color: rgba(33, 207, 255, 0.07);
  border: 1.5px solid #05bafe;
  border-radius: 20px;
  margin-bottom: 0;
  padding: 0 13px;
  line-height: 14px;
  display: flex;
  align-items: center;
}

/* ─── Newsletter heading ─────────────────────────────────────────────────────── */

.heading-2-news {
  margin: 0 0 15px 0;
  color: #fff;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 32px;
  font-weight: 700;
  line-height: 1.25;
  text-align: left;
}

.gradient-span {
  color: #21cfff;
  -webkit-text-fill-color: transparent;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  background-clip: text;
}

/* ─── Newsletter sub-text ────────────────────────────────────────────────────── */

.paragraph-small-4-gray {
  color: #c0dbff;
  margin-bottom: 0;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 24px;
}

/* ─── Newsletter form block ──────────────────────────────────────────────────── */

.footer-newsletter-form-block {
  background-color: transparent;
  border-radius: 0;
  margin-top: 13px;
  margin-bottom: 0;
  padding: 0;
}

/* ─── Form inner column ──────────────────────────────────────────────────────── */

.column-large {
  grid-column-gap: 24px;
  grid-row-gap: 24px;
  flex-direction: column;
  display: flex;
}

.column-large.row-gap-0 {
  grid-row-gap: 0px;
}

.column-tiny-2 {
  grid-column-gap: 4px;
  grid-row-gap: 4px;
  flex-direction: column;
  justify-content: center;
  display: flex;
  position: relative;
}

/* ─── Email input ────────────────────────────────────────────────────────────── */

.text-field-small {
  color: #23272f;
  border: 1px solid #edeff3;
  border-radius: 8px;
  min-height: 55px;
  margin-bottom: 0;
  padding: 8px 12px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 14px;
  line-height: 20px;
  width: 100%;
  outline: none;
  box-sizing: border-box;
  padding-right: 130px;
}

.text-field-small:focus {
  border-color: #b1bbc8;
}

.text-field-small::placeholder {
  color: #525f75;
}

/* ─── Submit button ──────────────────────────────────────────────────────────── */

.button-secondary-small {
  color: #fff;
  background-color: #23272f;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  border: 2px #23272f;
  border-radius: 10px;
  justify-content: center;
  align-items: center;
  padding: 12px 20px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 16px;
  font-weight: 700;
  text-decoration: none;
  display: flex;
  position: absolute;
  inset: auto 1.5% auto auto;
  top: 50%;
  transform: translateY(-50%);
  overflow: hidden;
  cursor: pointer;
  transition: opacity 0.2s;
}

.button-secondary-small:hover {
  opacity: 0.9;
  border-width: 0;
}

/* ─── Success / error message states ─────────────────────────────────────────── */

.success-message {
  color: #082753;
  background-color: #def4ff;
  border-radius: 12px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-weight: 500;
  padding: 12px 16px;
  font-size: 14px;
}

.error-message {
  color: #460906;
  background-color: #fff2eb;
  border-radius: 8px;
  padding: 12px 16px;
  margin-top: 8px;
  font-size: 14px;
}

/* ─── Privacy line under form ────────────────────────────────────────────────── */

.newsletter-btm-line {
  grid-column-gap: 5px;
  grid-row-gap: 5px;
  justify-content: center;
  align-items: center;
  margin-top: 5px;
