'use client';

import { AnimatePresence, motion, useReducedMotion } from 'framer-motion';
import { useEffect, useState } from 'react';
import styles from './hero.module.css';

const PHRASES = ['Ownership Driven', 'Without Hiring', 'On Demand'] as const;

export function Typewriter() {
  const [index, setIndex] = useState(0);
  const [mounted, setMounted] = useState(false);
  const prefersReducedMotion = useReducedMotion();

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    if (!mounted || prefersReducedMotion) return;
    const interval = setInterval(() => {
      setIndex((prev) => (prev + 1) % PHRASES.length);
    }, 2400);
    return () => clearInterval(interval);
  }, [mounted, prefersReducedMotion]);

  // SSR + first client render: emit a stable, non-animated span so hydration matches.
  // After mount, switch to the motion-driven version (or reduced-motion static span).
  if (!mounted || prefersReducedMotion) {
    return (
      <span
        className={`${styles['animate-span']} ${styles['typewriterContainer']}`}
      >
        {PHRASES[index]}
      </span>
    );
  }

  return (
    <span
      aria-live="polite"
      aria-atomic="true"
      className={styles['typewriterContainer']}
    >
      <AnimatePresence mode="wait">
        <motion.span
          key={index}
          className={`${styles['animate-span']} ${styles['typewriterWord']}`}
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -10 }}
          transition={{ duration: 0.28, ease: 'easeInOut' }}
        >
          {PHRASES[index]}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

