/* GuideJar embed wrapper */
.guidejarWrapper {
  position: relative;
  height: 0;
  width: 100%;
  overflow: hidden;
  z-index: var(--z-nav);
  border-radius: 10px;
  box-sizing: border-box;
  padding-bottom: calc(56.25% + 32px);
}

/* GuideJar iframe — fills the wrapper */
.guidejarIframe {
  position: absolute;
  inset: 0;
}

/* Typewriter span container */
.typewriterContainer {
  display: inline-block;
  min-width: 280px;
  min-height: 1.1em;
  text-align: left;
  vertical-align: baseline;
  /* Explicit fallback color so accessibility audits read correct contrast ratio.
     Visually the child .animate-span overrides this with #019ae6. */
  color: #019ae6;
}

/* Typewriter animated word */
.typewriterWord {
  display: inline-block;
  /* Explicit fallback so motion.span inherits readable color in audit contexts. */
  color: #019ae6;
}

.section-high-judge {
  background-color: #0000;
  background-image: url('/images/webflow/hero-background-1.png'), linear-gradient(#019ae614, #019ae600);

